using System;
using System.Collections.Generic;

public class Publisher
{
    public static event Action<string>? OnAlert;
    public static void Trigger(string msg) => OnAlert?.Invoke(msg);
}

public class LeakingSubscriber
{
    private readonly byte[] _heavyBuffer = new byte[1024 * 1024];
    private readonly int _id;

    public LeakingSubscriber(int id)
    {
        _id = id;
        Publisher.OnAlert += HandleAlert;
    }

    private void HandleAlert(string msg)
    {
    }

    public void Dispose()
    {
        Publisher.OnAlert -= HandleAlert;
    }
}

public class Program
{
    public static void Main()
    {
        Console.WriteLine("Membuat 5 subscriber...");
        for (int i = 1; i <= 5; i++)
        {
            var sub = new LeakingSubscriber(i);
            sub.Dispose();
        }

        GC.Collect();
        GC.WaitForPendingFinalizers();

        Console.WriteLine("Pembersihan selesai. Event subscription berhasil dicabut, tidak ada memory leak.");
    }
}
